import { ApiHideProperty } from '@nestjs/swagger';
import { IsBoolean, IsEnum, IsNotEmpty, IsObject, IsOptional, IsString } from 'class-validator';
import { BasicResponseDTO } from '../../basicResponseDTO';
import { CronExpression } from '@nestjs/schedule';
import { SchedulerEntity } from '../entities/scheduler.entity';
import { CreateUserDto } from '../../users/dto/create-user.dto';
import { EbsSnapshotDto } from '../../microservices/ebsSnapshotDataGatherer/dto/ebsSnapshot.dto';
import { EbsVolumeDataGathererDto } from '../../microservices/ebsVolumeDataGatherer/dto/ebsVolumeDataGatherer.dto';
import { NodeUptimeDto } from '../../microservices/instanceUpTime/dto/instanceUptimeDTO';
import { InstanceHistoryDto } from '../../microservices/reservedInstanceHistory/dto/reservedInstance.dto';
import { AggregationDto } from '../../dimensions/dto/aggregation.dto';
import { CreateBillingReportDto } from '../../billing/dto/createBillingReport.dto';

export enum SchedulerStatus {
    live = 'live',
    inactive = 'inactive',
}

export enum schedulerType {
    billing = 'billing',
    dimensionDataGathering = 'dimensionDataGathering',
    aggregation = 'aggregation',
}
enum expandedTimes {
    FIRST_DAY_OF_MONTH = '0 4 1 * *',
}
export enum SupportedMeasurementFrequencies {
    monthly = expandedTimes.FIRST_DAY_OF_MONTH,
    weekly = CronExpression.EVERY_WEEK,
    annual = CronExpression.EVERY_YEAR,
    perMinute = CronExpression.EVERY_MINUTE,
    everyFiveMinutes = CronExpression.EVERY_5_MINUTES,
    everyThirtyMinutes = CronExpression.EVERY_30_MINUTES,
    everyHour = CronExpression.EVERY_HOUR,
    daily = CronExpression.EVERY_DAY_AT_MIDNIGHT,
}
export class SchedulerDto {
    /**
     *  Represents the unqiue value of the scheduler, when creating a schedule this is optional, if none is provided a UUID will be generated for you.
     * @example e345f409-daca-4144-91d2-0a0f87c96581
     */
    @IsString()
    @IsOptional()
    public schedulerID?: string;

    /**
     *  Run the scheduled action immediately (and then again at the chosen rate)
     * @example true
     */
    @IsBoolean()
    @IsOptional()
    public startNow?: boolean;

    /**
     * Determines if the scheduler is live or inactive
     * @example 'live'
     * @example 'inactive'
     */
    @IsEnum(SchedulerStatus)
    @IsNotEmpty()
    public schedulerStatus: SchedulerStatus;

    /**
     * The unique identifier for the SaaS business
     * @example myCoolCorp
     */
    @ApiHideProperty()
    @IsString()
    @IsOptional()
    public businessID: string;

    /**
     * The subject associated with the user
     */
    @ApiHideProperty()
    @IsString()
    @IsOptional()
    public subject: CreateUserDto['subject'];
    /**
     * Controls the service called by the scheduler
     * @example "billing"
     */
    @IsEnum(schedulerType)
    @IsNotEmpty()
    public schedulerType: schedulerType;

    /**
     * The parameters to be passed to the scheduler service function
     * Cannot contain the substring "schedulerParam_" (without the quotes). This is due to how we internally model these keys
     * @example {"myCoolKey": "SomeReally1337Value"}
     */
    @IsObject()
    @IsNotEmpty()
    scheduleParameters:
        | EbsSnapshotDto
        | EbsVolumeDataGathererDto
        | NodeUptimeDto
        | InstanceHistoryDto
        | AggregationDto
        | CreateBillingReportDto;

    /**
     *  The rate for the scheduler to use
     * @example perMinute
     */
    @IsEnum(SupportedMeasurementFrequencies)
    @IsNotEmpty()
    public rate: SupportedMeasurementFrequencies;
}
export class SchedulerReadResponseDTO extends BasicResponseDTO {
    data: Array<SchedulerCreationResponse | SchedulerEntity>;
}

export class SchedulerCreationResponse {
    public key?: string;
    public cron?: string;
    public id?: string;
}

export class SchedulerDeletionResponse extends SchedulerReadResponseDTO {}
import { ApiHideProperty } from '@nestjs/swagger';
import { EbsSnapshotDto } from '../../microservices/ebsSnapshotDataGatherer/dto/ebsSnapshot.dto';
import { EbsVolumeDataGathererDto } from '../../microservices/ebsVolumeDataGatherer/dto/ebsVolumeDataGatherer.dto';
import { CreateUserDto } from '../../users/dto/create-user.dto';
import { SupportedMeasurementFrequencies, SchedulerStatus, schedulerType } from '../dto/scheduler.dto';
import { AggregationDto } from '../../dimensions/dto/aggregation.dto';
import { CreateBillingReportDto } from '../../billing/dto/createBillingReport.dto';
import { Ec2InstanceDataGathererDto } from '../../microservices/ec2InstanceDataGatherer/Dto/ec2InstanceDataGatherer.dto';
import { Ec2EgressDataGathererDto } from '../../microservices/ec2EgressDataGatherer/Dto/ec2EgressDataGatherer.dto';

export class SchedulerEntity {
    @ApiHideProperty()
    public static _measurement = 'SchedulerConfig';

    /**
     *  Represents the unqiue value of the scheduler
     * @example e345f409-daca-4144-91d2-0a0f87c96581
     */
    public schedulerID?: string;

    /**
     * Determines if the scheduler is live or inactive
     * @example 'live'
     * @example 'inactive'
     */
    public schedulerStatus: SchedulerStatus;

    @ApiHideProperty()
    public businessID?: string;

    /**
     * Controls the service called by the scheduler
     * @example "billing"
     */
    public schedulerType: schedulerType;

    /**
     * The parameters to be passed to the scheduler service function
     * Cannot contain the substring "schedulerParam_" (without the quotes). This is due to how we internally model these keys
     * @example {"myCoolKey": "SomeReally1337Value"}
     * @example {"serviceId": "1234abc"}
     * @example {"iamRole": "myCoolIAMRole::", "ExternalID": "foobar"}
     */
    public scheduleParameters:
        | Ec2InstanceDataGathererDto
        | EbsSnapshotDto
        | EbsVolumeDataGathererDto
        | AggregationDto
        | CreateBillingReportDto
        | Ec2EgressDataGathererDto;

    /**
     *  The rate for the scheduler to use
     * @example perMinute
     */
    public rate: SupportedMeasurementFrequencies;

    /**
     * The subject associated with the user
     */
    public subject: CreateUserDto['subject'];

    constructor({
        schedulerStatus = SchedulerStatus.live,
        schedulerType,
        businessID,
        scheduleParameters,
        rate,
        schedulerID,
        subject,
    }) {
        this.schedulerStatus = schedulerStatus;
        this.schedulerType = schedulerType;
        this.businessID = businessID;
        this.scheduleParameters = scheduleParameters;
        this.rate = rate;
        this.schedulerID = schedulerID;
        this.subject = subject;
    }
}
import { Controller, Get, Post, Body, Param, Delete, UseGuards, Req, Query } from '@nestjs/common';
import { SchedulerService } from './scheduler.service';
import { SchedulerDto, SchedulerReadResponseDTO } from './dto/scheduler.dto';
import { ApiOkResponse } from '@nestjs/swagger';
import { BasicResponseDTO } from '../basicResponseDTO';
import { AuthGuard } from '@nestjs/passport';
import { Request } from 'express';
import { randomUUID } from 'crypto';

@Controller('scheduler')
export class SchedulerController {
    constructor(private readonly schedulerService: SchedulerService) {}

    /**
     * Create a customer or update a schedule
     */
    @ApiOkResponse({
        description: 'Response structure  for creating / updating a schedule',
        type: BasicResponseDTO,
    })
    @UseGuards(AuthGuard('jwt'))
    @Post()
    create(@Body() schedulerDto: SchedulerDto, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID, sub } = request.user;
        return this.schedulerService.create({ ...schedulerDto, businessID, subject: sub });
    }
    /**
     * Create a customer or update a schedule
     */
    @ApiOkResponse({
        description: 'Response structure  for creating / updating a schedule',
        type: BasicResponseDTO,
    })
    @UseGuards(AuthGuard('jwt'))
    @Post('emit')
    emitOne(@Body() payload, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID, sub } = request.user;
        return this.schedulerService.emitOne({ schedulerId: randomUUID(), payload: { ...payload, businessID, sub } });
    }

    /**
     * Get all schedules assocaited with your account
     */
    @ApiOkResponse({
        description: 'Response structure for getting all schedules',
        type: SchedulerReadResponseDTO,
    })
    @UseGuards(AuthGuard('jwt'))
    @Get()
    findAll(@Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;

        return this.schedulerService.findAll({ businessID });
    }

    /**
     * Get a single Schedule based on ID
     */
    @ApiOkResponse({
        description: 'Response structure for getting a single schedules',
        type: SchedulerReadResponseDTO,
    })
    @UseGuards(AuthGuard('jwt'))
    @Get(':schedulerID')
    findOne(@Param('schedulerID') schedulerID: string, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;

        return this.schedulerService.findOne({ businessID, schedulerID });
    }

    /**
     * Remove a schdule, this will stop the schedule before the next run,
     * if a run recently happened or is happening it will not stop it from executing
     */
    @UseGuards(AuthGuard('jwt'))
    @Delete(':schedulerID')
    remove(
        @Param('schedulerID') schedulerID: string,
        @Query('isBillingQueue') isBillingQueue: string,
        @Req() request: Request
    ) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;

        return this.schedulerService.remove({ businessID, schedulerID, isBillingQueue: isBillingQueue !== undefined });
    }
}
import { Module, forwardRef } from '@nestjs/common';
