/**
 * Creates the customer level, monthly, billing schedule for a customer.
 * The schedulerID matches the customerId so the schedule can always be located (and replaced) by customer.
 */
private async createBillingScheduleForCustomer({
    customerId,
    businessID,
    subject,
}: {
    customerId: string;
    businessID: string;
    subject?: string;
}) {
    return this.schedulerService.create({
        schedulerID: customerId,
        schedulerType: schedulerType.billing,
        schedulerStatus: SchedulerStatus.live,
        scheduleParameters: { customerId, businessID },
        rate: SupportedMeasurementFrequencies.monthly,
        subject,
        businessID,
    });
}

/**
 * Removes the billing schedule for a customer, a missing schedule is not an error.
 */
private async removeBillingScheduleForCustomer({ customerId, businessID }) {
    try {
