describe('BillingService', () => {
    const businessID = 'myCoolCorp';
    const customerId = 'b9459f53-054b-4437-8ecd-b6f8070344fc';
    const invoiceId = 'a2a4d0c8-6a55-4e39-8c02-2f01b6f1c6f0';

    let service: BillingService;
    const mockLoadPoints = jest.fn();
    const mockTag = jest.fn();
    const mockStringField = jest.fn();
    const mockGenerateInvoiceForUsageTotal = jest.fn(async () => ({ invoiceId, message: 'Generated invoice' }));
    const mockFindOne = jest.fn(async () => ({
        data: [{ customerId, offering: { billingCycle: validBillingCycles.monthly } }],
        message: 'Found Customer',
    }));
    const publishEventSpy = jest.spyOn(AuditService, 'publishEvent').mockImplementation(() => undefined);

    const buildJob = () =>
        ({ data: { businessID, scheduleParameters: { customerId, businessID } } } as Job<SchedulerEntity>);

    beforeEach(async () => {
        process.env.STAGE = 'unit-test';
        const module: TestingModule = await Test.createTestingModule({
            providers: [BillingService],
            imports: [],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => ({ tag: mockTag, stringField: mockStringField }),
                    };
                }
                if (token === CustomerService) {
                    return { findOne: mockFindOne };
                }
                if (token === InvoicesService) {
                    return { generateInvoiceForUsageTotal: mockGenerateInvoiceForUsageTotal };
                }
            })
            .compile();

        service = module.get<BillingService>(BillingService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    it('should generate the invoice for the customer over the offering billing cycle', async () => {
        await service.create(buildJob());

        expect(mockFindOne).toBeCalledWith({ customerId, businessID });
        const { startTime, endTime } = Billing.billingCycleToTimeRange(validBillingCycles.monthly);
        expect(mockGenerateInvoiceForUsageTotal).toBeCalledWith({
            businessID,
            customerId,
            start: startTime,
            end: endTime,
        });
    });

    it('should store a billing record holding the generated invoiceId', async () => {
        await service.create(buildJob());

        expect(mockLoadPoints).toBeCalledTimes(1);
        expect(mockTag).toBeCalledWith('invoiceId', invoiceId);
        expect(mockTag).toBeCalledWith('customerId', customerId);
        expect(mockTag).toBeCalledWith('businessID', businessID);
    });

    it('should not bill a customer without an offering', async () => {
        mockFindOne.mockResolvedValueOnce({ data: [{ customerId, offering: undefined }], message: 'Found Customer' });

        await service.create(buildJob());

        expect(mockGenerateInvoiceForUsageTotal).not.toBeCalled();
        expect(mockLoadPoints).not.toBeCalled();
    });

    it('should audit failures instead of storing a partial billing record', async () => {
        mockGenerateInvoiceForUsageTotal.mockRejectedValueOnce(new Error('invoice generation blew up'));

        await service.create(buildJob());

        expect(mockLoadPoints).not.toBeCalled();
        expect(publishEventSpy).toBeCalledWith(expect.objectContaining({ topic: AuditScope.ERROR }));
    });
});

